public class Attribute_getValue_TriageGen1Test {











    @Test
    public void testGetValueWithClone() {
        Attribute original = new Attribute("key", "value");
        Attribute cloned = original.clone();
        assertEquals("value", cloned.getValue());
        cloned.setValue("new value");
        assertEquals("value", original.getValue()); // Ensure original is unaffected
    }














}

